import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_reality_correction_pass, get_correction_applier

_EMPTY = {"correction_plan_json": "{}", "apply_result_json": "{}", "clean": False,
          "op_count": 0, "applied_count": 0, "exec_out": True}

class Hou_Mcp_Reality_Correction(BaseNode):
    name = "hou_mcp_reality_correction"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("scene_layout_json", "string", widget_type="text", default="{}")
        self.add_input("node_path_map_json", "string", widget_type="text", default="{}")
        self.add_input("apply", "bool", widget_type="checkbox", default=False)
        self.add_output("correction_plan_json")
        self.add_output("apply_result_json")
        self.add_output("clean", "bool")
        self.add_output("op_count", "int")
        self.add_output("applied_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            scene = json.loads((inputs.get("scene_layout_json") or "{}").strip() or "{}")
            path_map = json.loads((inputs.get("node_path_map_json") or "{}").strip() or "{}")
        except Exception:
            self.log_error("scene_layout_json / node_path_map_json is not valid JSON.")
            return dict(_EMPTY)
        try:
            plan = get_reality_correction_pass().build_correction_plan(scene)
            for f in plan.findings:
                self.log_error(f)
            apply_result = {}
            applied = 0
            if inputs.get("apply") and path_map:
                res = get_correction_applier().apply(
                    [o.to_dict() for o in plan.ops], path_map)
                apply_result = res.to_dict()
                applied = res.applied
            return {
                "correction_plan_json": json.dumps(plan.to_dict(), sort_keys=True, indent=2),
                "apply_result_json": json.dumps(apply_result, sort_keys=True, indent=2),
                "clean": plan.clean,
                "op_count": len(plan.ops),
                "applied_count": applied,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Reality correction failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Reality_Correction
